<?php
require_once __DIR__ . '/../../includes/auth-check.php';
require_once __DIR__ . '/../../includes/admin-ui.php';
require_once __DIR__ . '/../../includes/analytics.php';
require_once __DIR__ . '/../../includes/cache.php';
admin_require_permission($pdo,$admin,'manage_wordbank');
$errorMessage='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=request_string($_POST, 'action', '');
 try{
  if($action==='review_setting'){
   save_setting($pdo,'generator_review_only',isset($_POST['generator_review_only']),(int)$admin['id'],true);
   audit_log($pdo,(int)$admin['id'],'wordbank.review_filter_updated','generator','review-only');cache_clear_all();flash('success','English review filter updated.');redirect_to('admin/domain-brain/index.php');
  }
  if($action==='term_delete'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid vocabulary entry.');
   $pdo->prepare('DELETE FROM wordbank_terms WHERE id=:id')->execute(['id'=>$id]);audit_log($pdo,(int)$admin['id'],'wordbank.term_deleted','wordbank_term',(string)$id);cache_clear_all();flash('success','Word removed.');redirect_to('admin/domain-brain/index.php');
  }
  if($action==='term_save'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0;
   $word=strtolower(trim(substr(request_string($_POST, 'word', ''),0,48)));
   $type=in_array(($_POST['term_type']??''),['curated','brandable','long_partner'],true)?(string)$_POST['term_type']:'curated';
   $reviewed=isset($_POST['english_reviewed'])?1:0;$active=isset($_POST['is_active'])?1:0;$note=trim(substr(strip_tags(request_string($_POST, 'note', '')),0,255));
   if(!preg_match('/^[a-z0-9-]{2,48}$/',$word))throw new RuntimeException('A word must contain 2–48 lowercase English letters, numbers or hyphens.');
   if($type==='long_partner'&&strlen($word)<7)throw new RuntimeException('A long-partner word must contain at least 7 characters.');
   if($id){$save=$pdo->prepare('UPDATE wordbank_terms SET word=:word,term_type=:type,english_reviewed=:reviewed,is_active=:active,note=:note,updated_by=:admin WHERE id=:id');$save->execute(['word'=>$word,'type'=>$type,'reviewed'=>$reviewed,'active'=>$active,'note'=>$note,'admin'=>(int)$admin['id'],'id'=>$id]);}
   else{$save=$pdo->prepare('INSERT INTO wordbank_terms(word,term_type,english_reviewed,is_active,note,created_by,updated_by) VALUES(:word,:type,:reviewed,:active,:note,:created,:updated)');$save->execute(['word'=>$word,'type'=>$type,'reviewed'=>$reviewed,'active'=>$active,'note'=>$note,'created'=>(int)$admin['id'],'updated'=>(int)$admin['id']]);$id=(int)$pdo->lastInsertId();}
   audit_log($pdo,(int)$admin['id'],'wordbank.term_saved','wordbank_term',(string)$id,$word.' · '.$type);cache_clear_all();flash('success','Vocabulary entry saved.');redirect_to('admin/domain-brain/index.php');
  }
  if($action==='category_delete'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
   if(!$id)throw new RuntimeException('Invalid category.');
   $check=$pdo->prepare('SELECT category_key FROM wordbank_categories WHERE id=:id LIMIT 1');$check->execute(['id'=>$id]);$categoryKey=(string)$check->fetchColumn();
   if($categoryKey===''||$categoryKey==='smart')throw new RuntimeException('The built-in general category cannot be deleted.');
   $pdo->prepare('DELETE FROM wordbank_categories WHERE id=:id')->execute(['id'=>$id]);audit_log($pdo,(int)$admin['id'],'wordbank.category_deleted','wordbank_category',$categoryKey);cache_clear_all();flash('success','Category deleted.');redirect_to('admin/domain-brain/index.php');
  }
  if($action==='category_save'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0;
   $key=strtolower(trim(substr(request_string($_POST, 'category_key', ''),0,60)));
   $label=trim(substr(strip_tags(request_string($_POST, 'label', '')),0,120));$description=trim(substr(strip_tags(request_string($_POST, 'description', '')),0,255));
   $keywords=trim(request_string($_POST, 'detection_keywords', ''));$preferred=trim(request_string($_POST, 'preferred_words', ''));$order=max(-10000,min(10000,(int)($_POST['display_order']??0)));$active=isset($_POST['is_active'])?1:0;
   if(!preg_match('/^[a-z][a-z0-9_]{1,59}$/',$key)||$label==='')throw new RuntimeException('Use a unique category key (lowercase letters, numbers, underscores) and a label.');
   $parseList=static function(string $value):array{$items=preg_split('/[\r\n,]+/',$value)?:[];$clean=[];foreach($items as $item){$item=strtolower(trim($item));if($item==='')continue;if(strlen($item)>48||!preg_match('/^[a-z0-9-]+$/',$item))throw new RuntimeException('Category keywords and preferred words must be single alphanumeric words.');$clean[]=$item;}return array_values(array_unique(array_slice($clean,0,150)));};
   $keywordsJson=json_encode($parseList($keywords),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$preferredJson=json_encode($parseList($preferred),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
   if($id){$existing=$pdo->prepare('SELECT category_key FROM wordbank_categories WHERE id=:id');$existing->execute(['id'=>$id]);$oldKey=$existing->fetchColumn();if(!$oldKey)throw new RuntimeException('Category not found.');if($oldKey==='smart'&&$key!=='smart')throw new RuntimeException('The built-in general category key cannot be changed.');$save=$pdo->prepare('UPDATE wordbank_categories SET category_key=:key,label=:label,description=:description,detection_keywords_json=:keywords,preferred_words_json=:preferred,display_order=:sort,is_active=:active,updated_by=:admin WHERE id=:id');$save->execute(['key'=>$key,'label'=>$label,'description'=>$description,'keywords'=>$keywordsJson,'preferred'=>$preferredJson,'sort'=>$order,'active'=>$active,'admin'=>(int)$admin['id'],'id'=>$id]);}
   else{$save=$pdo->prepare('INSERT INTO wordbank_categories(category_key,label,description,detection_keywords_json,preferred_words_json,display_order,is_active,updated_by) VALUES(:key,:label,:description,:keywords,:preferred,:sort,:active,:admin)');$save->execute(['key'=>$key,'label'=>$label,'description'=>$description,'keywords'=>$keywordsJson,'preferred'=>$preferredJson,'sort'=>$order,'active'=>$active,'admin'=>(int)$admin['id']]);$id=(int)$pdo->lastInsertId();}
   audit_log($pdo,(int)$admin['id'],'wordbank.category_saved','wordbank_category',$key,$label);cache_clear_all();flash('success','Category saved.');redirect_to('admin/domain-brain/index.php');
  }
 }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();error_log('Domain brain save: '.$error->getMessage());$errorMessage=$error instanceof RuntimeException?$error->getMessage():'Could not save the vocabulary or category. Check for duplicate words or keys.';}
}
$search=trim(substr(request_string($_GET, 'q', ''),0,48));$typeFilter=in_array(($_GET['type']??''),['curated','brandable','long_partner'],true)?(string)$_GET['type']:'';
$where='1=1';$params=[];if($search!==''){$where.=' AND word LIKE :q';$params['q']='%'.$search.'%';}if($typeFilter!==''){$where.=' AND term_type=:type';$params['type']=$typeFilter;}
$termsQuery=$pdo->prepare("SELECT id,word,term_type,english_reviewed,is_active,note,updated_at FROM wordbank_terms WHERE $where ORDER BY term_type,word LIMIT 300");$termsQuery->execute($params);$terms=$termsQuery->fetchAll();
$termEdit=null;if(isset($_GET['edit_term'])){$get=$pdo->prepare('SELECT * FROM wordbank_terms WHERE id=:id');$get->execute(['id'=>filter_var($_GET['edit_term'],FILTER_VALIDATE_INT)]);$termEdit=$get->fetch()?:null;}
$categories=$pdo->query('SELECT * FROM wordbank_categories ORDER BY display_order,label')->fetchAll();$categoryEdit=null;if(isset($_GET['edit_category'])){$get=$pdo->prepare('SELECT * FROM wordbank_categories WHERE id=:id');$get->execute(['id'=>filter_var($_GET['edit_category'],FILTER_VALIDATE_INT)]);$categoryEdit=$get->fetch()?:null;}
$reviewOnly=(bool)setting($pdo,'generator_review_only',false);$counts=$pdo->query('SELECT term_type,COUNT(*) AS total,SUM(is_active=1) AS active,SUM(english_reviewed=1) AS reviewed FROM wordbank_terms GROUP BY term_type')->fetchAll();
admin_header($pdo,$admin,'Domain brain');
?>
<?php if($errorMessage!==''):?><div class="notice notice-error" role="alert"><?=e($errorMessage)?></div><?php endif;?>
<section class="admin-card"><h2>Generator vocabulary controls</h2><div class="admin-stats"><?php foreach($counts as $count):?><article class="admin-stat"><span><?=e(str_replace('_',' ',ucfirst($count['term_type'])))?></span><strong><?=number_format((int)$count['active'])?></strong><small><?=number_format((int)$count['reviewed'])?> marked as human-reviewed</small></article><?php endforeach;?></div><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="review_setting"><label class="inline-check"><input type="checkbox" name="generator_review_only" value="1" <?=$reviewOnly?'checked':''?>><span>In strict mode, use only terms explicitly marked as human-reviewed (including 7+ partner words).</span></label><p>Off by default to preserve the supplied curated list. The flag records an editorial choice; it is not a dictionary, legal or trademark certification.</p><button class="button button-small" type="submit">Save review filter</button></form></section>
<div class="admin-columns"><section class="admin-card"><h2><?= $termEdit?'Edit':'Add' ?> vocabulary term</h2><form class="admin-form" method="post"><?=csrf_field()?><?php if($termEdit):?><input type="hidden" name="id" value="<?=(int)$termEdit['id']?>"><?php endif;?><input type="hidden" name="action" value="term_save"><div class="form-row"><div class="field"><label for="word">Word or component</label><input id="word" name="word" maxlength="48" pattern="[a-zA-Z0-9-]{2,48}" required value="<?=e($termEdit['word']??'')?>"></div><div class="field"><label for="term_type">Word-list type</label><select id="term_type" name="term_type"><?php foreach(['curated'=>'Curated (strict list)','brandable'=>'Brandable (creative)','long_partner'=>'Long partner (7+)'] as $typeKey=>$typeLabel):?><option value="<?=e($typeKey)?>" <?=($termEdit['term_type']??'curated')===$typeKey?'selected':''?>><?=e($typeLabel)?></option><?php endforeach;?></select></div></div><div class="field"><label for="note">Editorial note (optional)</label><input id="note" name="note" maxlength="255" value="<?=e($termEdit['note']??'')?>"></div><label class="inline-check"><input type="checkbox" name="english_reviewed" value="1" <?=($termEdit&&$termEdit['english_reviewed'])?'checked':''?>><span>Mark as human-reviewed English vocabulary</span></label><label class="inline-check"><input type="checkbox" name="is_active" value="1" <?=!$termEdit||$termEdit['is_active']?'checked':''?>><span>Include in generator</span></label><div class="admin-actions"><button class="button button-primary" type="submit">Save term</button><?php if($termEdit):?><a href="<?=e(app_url('admin/domain-brain/index.php'))?>">Cancel</a><?php endif;?></div></form></section>
<section class="admin-card"><h2><?= $categoryEdit?'Edit':'Add' ?> category</h2><form class="admin-form" method="post"><?=csrf_field()?><?php if($categoryEdit):?><input type="hidden" name="id" value="<?=(int)$categoryEdit['id']?>"><?php endif;?><input type="hidden" name="action" value="category_save"><div class="form-row"><div class="field"><label for="category_key">Category key</label><input id="category_key" name="category_key" maxlength="60" pattern="[a-z][a-z0-9_]{1,59}" required value="<?=e($categoryEdit['category_key']??'')?>" <?=($categoryEdit['category_key']??'')==='smart'?'readonly':''?>></div><div class="field"><label for="category_label">Display label</label><input id="category_label" name="label" maxlength="120" required value="<?=e($categoryEdit['label']??'')?>"></div></div><div class="field"><label for="description">Description</label><input id="description" name="description" maxlength="255" value="<?=e($categoryEdit['description']??'')?>"></div><div class="field"><label for="detection_keywords">Auto-detection keywords (comma or newline separated)</label><textarea id="detection_keywords" name="detection_keywords" rows="4"><?=e(implode("\n",json_decode((string)($categoryEdit['detection_keywords_json']??'[]'),true)?:[]))?></textarea></div><div class="field"><label for="preferred_words">Preferred generator partners (comma or newline separated)</label><textarea id="preferred_words" name="preferred_words" rows="4"><?=e(implode("\n",json_decode((string)($categoryEdit['preferred_words_json']??'[]'),true)?:[]))?></textarea></div><div class="form-row"><div class="field"><label for="display_order">Display order</label><input id="display_order" name="display_order" type="number" min="-10000" max="10000" value="<?=e($categoryEdit['display_order']??10)?>"></div><label class="inline-check"><input type="checkbox" name="is_active" value="1" <?=!$categoryEdit||$categoryEdit['is_active']?'checked':''?>><span>Show category in generator</span></label></div><div class="admin-actions"><button class="button button-primary" type="submit">Save category</button><?php if($categoryEdit):?><a href="<?=e(app_url('admin/domain-brain/index.php'))?>">Cancel</a><?php endif;?></div></form></section></div>
<section class="admin-card"><h2>Vocabulary terms (latest 300 matching)</h2><form class="admin-filter" method="get"><input name="q" type="search" value="<?=e($search)?>" placeholder="Find a term"><select name="type"><option value="">All word types</option><?php foreach(['curated','brandable','long_partner'] as $option):?><option value="<?=e($option)?>" <?=$typeFilter===$option?'selected':''?>><?=e(ucfirst(str_replace('_',' ',$option)))?></option><?php endforeach;?></select><button class="button button-small" type="submit">Filter</button></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Word</th><th>Type / review</th><th>State</th><th>Actions</th></tr></thead><tbody><?php foreach($terms as $term):?><tr><td><strong><?=e($term['word'])?></strong><?php if($term['note']):?><br><small><?=e($term['note'])?></small><?php endif;?></td><td><?=e(ucfirst(str_replace('_',' ',$term['term_type'])))?><br><span class="admin-badge"><?=$term['english_reviewed']?'Human-reviewed':'Not reviewed'?></span></td><td><?=$term['is_active']?'Active':'Inactive'?></td><td><div class="admin-actions"><a href="<?=e(app_url('admin/domain-brain/index.php?edit_term='.(int)$term['id']))?>">Edit</a><form method="post" data-confirm="Remove this term from the word bank?"><?=csrf_field()?><input type="hidden" name="action" value="term_delete"><input type="hidden" name="id" value="<?=(int)$term['id']?>"><button class="admin-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?><?php if(!$terms):?><tr><td colspan="4">No terms found.</td></tr><?php endif;?></tbody></table></div></section>
<section class="admin-card"><h2>Industry categories</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Category</th><th>Keywords / preferred words</th><th>Order</th><th>Actions</th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td><strong><?=e($category['label'])?></strong><br><code><?=e($category['category_key'])?></code><br><small><?=e($category['description'])?></small></td><td><?=number_format(count(json_decode((string)$category['detection_keywords_json'],true)?:[]))?> detection keywords<br><?=number_format(count(json_decode((string)$category['preferred_words_json'],true)?:[]))?> preferred words</td><td><?=(int)$category['display_order']?></td><td><div class="admin-actions"><a href="<?=e(app_url('admin/domain-brain/index.php?edit_category='.(int)$category['id']))?>">Edit</a><?php if($category['category_key']!=='smart'):?><form method="post" data-confirm="Delete this category? Terms stay in the word bank."><?=csrf_field()?><input type="hidden" name="action" value="category_delete"><input type="hidden" name="id" value="<?=(int)$category['id']?>"><input type="hidden" name="category_key" value="<?=e($category['category_key'])?>"><button class="admin-danger" type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php admin_footer(); ?>
